196					// 被拒绝的批次不占用 p1：随后单独提交相同的合法付款按首次付款
197					// settled（不是 duplicate/conflict），手续费 4、扣款 1504、余额
198					// 496，成功序号紧接原有历史为 2，没有空缺。
199					r = submitAtomic(t, entry, ledgerPath, atomicValidP1Batch)
200					if r.code != 0 {
201						t.Fatalf("valid p1 after rejected batch: code=%d err=%s", r.code, r.err)
202					}
203					var res struct {
204						Results []struct {
205							ID     string  `json:"id"`
206							Status string  `json:"status"`
207							Record *struct {
208								Fee     int64 `json:"fee"`
209								Charged int64 `json:"charged"`
210								Seq     int64 `json:"seq"`
211							} `json:"record"`
212						} `json:"results"`
213					}
214					if err := json.Unmarshal([]byte(r.out), &res); err != nil {
215						t.Fatalf("decode valid submit: %v\n%s", err, r.out)
216					}
217					if len(res.Results) != 1 {
218						t.Fatalf("want exactly 1 result, got %d: %s", len(res.Results), r.out)
219					}
220					item := res.Results[0]
221					if item.ID != "p1" || item.Status != "settled" || item.Record == nil {
222						t.Fatalf("p1 must settle for the first time: %+v", item)
223					}
224					if item.Record.Fee != 4 || item.Record.Charged != 1504 || item.Record.Seq != 2 {
225						t.Fatalf("p1 record fee=%d charged=%d seq=%d, want 4/1504/2",
226							item.Record.Fee, item.Record.Charged, item.Record.Seq)
227					}
228	
229					snap := queryAtomic(t, ledgerPath)
230					if snap.balance != 496 {
231						t.Fatalf("balance after p1=%d want 496", snap.balance)
232					}
233					if ids := joinComma(snap.paymentIDs); ids != "h1,p1" {
234						t.Fatalf("payment ids=%v want [h1 p1]", snap.paymentIDs)
235					}
236					if len(snap.paymentSeq) != 2 || snap.paymentSeq[0] != 1 || snap.paymentSeq[1] != 2 {
237						t.Fatalf("payment seqs=%v want [1 2]", snap.paymentSeq)
238					}
239					if ids := joinComma(snap.refundIDs); ids != "r1" {
240						t.Fatalf("refund history must stay [r1], got %v", snap.refundIDs)
241					}
242	
243					// 再次提交相同 p1 现在必须是 duplicate 且不二次扣款，
244					// 反向证明上一笔是首次成功而非被拒绝批次的残留记录。
245					r = submitAtomic(t, entry, ledgerPath, atomicValidP1Batch)
246					if r.code != 0 {
247						t.Fatalf("duplicate resubmit code=%d err=%s", r.code, r.err)
248					}
249					var dup struct {
250						Results []struct {
251							Status string `json:"status"`
252						} `json:"results"`
253					}
254					if err := json.Unmarshal([]byte(r.out), &dup); err != nil {
255						t.Fatal(err)
256					}
257					if len(dup.Results) != 1 || dup.Results[0].Status != "duplicate" {
258						t.Fatalf("second p1 must be duplicate: %s", r.out)
259					}
260					if snap := queryAtomic(t, ledgerPath); snap.balance != 496 {
261						t.Fatalf("duplicate resubmit charged again: balance=%d", snap.balance)
262					}
263				})
264			}
265		}
266	}
267	
268	// TestCLISubmitAcceptsTrailingWhitespace 锁定“完整 JSON 之后只有空白”与
269	// “第二个 JSON 文档”的区别：空格、制表符、换行（含 CRLF）是合法尾随空白，
270	// 批次必须正常提交，不能与尾随文档混淆。两个入口行为一致。
271	func TestCLISubmitAcceptsTrailingWhitespace(t *testing.T) {
272		suffixes := []string{
273			"   ",
274			"\n",
275			"\r\n",
276			" \t\n  \r\n\t",
277		}
278		entries := []string{"stdin", "file"}
279		for _, suffix := range suffixes {
280			for _, entry := range entries {
281				t.Run("whitespace_via_"+entry, func(t *testing.T) {
282					ledgerPath, _ := setupAtomicLedger(t)
283					r := submitAtomic(t, entry, ledgerPath, atomicValidP1Batch+suffix)
284					if r.code != 0 {
285						t.Fatalf("trailing whitespace must be accepted: code=%d err=%s", r.code, r.err)
286					}
287					var res struct {
288						Results []struct {
289							Status string  `json:"status"`
290							Record *struct {
291								Seq int64 `json:"seq"`
292							} `json:"record"`
293						} `json:"results"`
294					}
295					if err := json.Unmarshal([]byte(r.out), &res); err != nil {
296						t.Fatalf("decode: %v\n%s", err, r.out)
297					}
298					if len(res.Results) != 1 || res.Results[0].Status != "settled" ||
299						res.Results[0].Record == nil || res.Results[0].Record.Seq != 2 {
300						t.Fatalf("whitespace-suffixed batch must settle p1 at seq 2: %s", r.out)
301					}
302					if snap := queryAtomic(t, ledgerPath); snap.balance != 496 {
303						t.Fatalf("balance=%d want 496", snap.balance)
304					}
305				})
306			}
307		}
308	}
309	
310	// TestCLISubmitPerItemZeroAmountDoesNotAbortBatch 是对照场景：JSON 与字段类型
311	// 都合法、仅后项金额明确为整数 0 时属于逐项业务失败而非整批输入错误——
312	// 整批退出 0，结果按输入顺序为第一项 settled、后项 invalid_parameter；
313	// 前项扣款与记录保留（p1 seq=2、余额 496），后项不扣款、不留成功记录。
314	func TestCLISubmitPerItemZeroAmountDoesNotAbortBatch(t *testing.T) {
315		for _, entry := range []string{"stdin", "file"} {
316			t.Run("zero_amount_via_"+entry, func(t *testing.T) {
317				ledgerPath, baseline := setupAtomicLedger(t)
318				body := `{"fee_bps":30,"intents":[
319	  {"id":"p1","account":"aa","paymaster":"pm-1","asset":"usdc","amount":1500,"nonce":1,"state":"pending"},
320	  {"id":"z1","account":"aa","asset":"usdc","amount":0}
321	]}`
322				r := submitAtomic(t, entry, ledgerPath, body)
323				if r.code != 0 {
324					t.Fatalf("per-item failures are normal results, exit must be 0: %s", r.err)
325				}
326				var res struct {
327					Results []struct {
328						ID     string  `json:"id"`
329						Status string  `json:"status"`
330						Reason string  `json:"reason"`
331						Record *struct {
332							Fee     int64 `json:"fee"`
333							Charged int64 `json:"charged"`
334							Seq     int64 `json:"seq"`
335						} `json:"record"`
336					} `json:"results"`
337				}
338				if err := json.Unmarshal([]byte(r.out), &res); err != nil {
339					t.Fatalf("decode: %v\n%s", err, r.out)
340				}
341				if len(res.Results) != 2 {
342					t.Fatalf("want 2 per-item results, got %d: %s", len(res.Results), r.out)
343				}
344				first, second := res.Results[0], res.Results[1]
345				if first.ID != "p1" || first.Status != "settled" || first.Record == nil {
346					t.Fatalf("first item must settle: %+v", first)
347				}
348				if first.Record.Fee != 4 || first.Record.Charged != 1504 || first.Record.Seq != 2 {
349					t.Fatalf("first item record=%+v, want fee 4 charged 1504 seq 2", first.Record)
350				}
351				if second.ID != "z1" || second.Status != "invalid_parameter" || second.Record != nil {
352					t.Fatalf("zero amount must be a per-item invalid_parameter with no record: %+v", second)
353				}
354				if second.Reason != "amount must be a positive int64" {
355					t.Fatalf("zero amount reason=%q", second.Reason)
356				}
357	
358				// 前项扣款保留，后项不留成功记录：余额 496，历史 [h1(seq1) p1(seq2)]，
359				// 没有 z1，序号无空缺；退款历史不变。账本文件相较基线确实发生了一次
360				// 正常落账（与整批拒绝时的“逐字节不变”形成对照）。
361				snap := queryAtomic(t, ledgerPath)
362				if snap.balance != 496 {
363					t.Fatalf("balance=%d want 496", snap.balance)
364				}
365				if ids := joinComma(snap.paymentIDs); ids != "h1,p1" {
366					t.Fatalf("payment ids=%v want [h1 p1] (z1 must leave no record)", snap.paymentIDs)
367				}
368				if len(snap.paymentSeq) != 2 || snap.paymentSeq[1] != 2 {
369					t.Fatalf("payment seqs=%v want [1 2]", snap.paymentSeq)
370				}
371				if ids := joinComma(snap.refundIDs); ids != "r1" {
372					t.Fatalf("refund ids=%v want [r1]", snap.refundIDs)
373				}
374				if changed, err := os.ReadFile(ledgerPath); err != nil {
375					t.Fatal(err)
376				} else if bytes.Equal(baseline, changed) {
377					t.Fatalf("settled first item must have persisted the ledger file")
378				}
379			})
380		}
381	}
